B.atL=new A.iN("Allah","\u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0627\u0644\u0644\u0647","Belief in Allah, His Oneness, His names, and His attributes, without likening Him to creation.")
B.atQ=new A.iN("The angels","\u0627\u0644\u0645\u0644\u0627\u0626\u0643\u0629","Belief in the angels, created from light. They do not disobey Allah.")
B.atN=new A.iN("The books","\u0627\u0644\u0643\u062a\u0628","Belief in the books Allah revealed, including the Torah, the Gospel, the Psalms, and the Quran, which is the final Book.")
B.atJ=new A.iN("The messengers","\u0627\u0644\u0631\u0633\u0644","Belief in the messengers, from Adam to Muhammad \ufdfa, the seal of the prophets.")
B.atH=new A.iN("The Last Day","\u0627\u0644\u064a\u0648\u0645 \u0627\u0644\u0622\u062e\u0631","Belief in the resurrection, the reckoning, Paradise, and Hellfire.")
B.atO=new A.iN("The decree","\u0627\u0644\u0642\u062f\u0631","Belief that everything, the good of it and the bad of it, is by the decree of Allah.")
B.a2N=A.a(s([B.atL,B.atQ,B.atN,B.atJ,B.atH,B.atO]),t.ud)
B.atz=new A.QE("Six Pillars of Iman","\u0623\u0631\u0643\u0627\u0646 \u0627\u0644\u0625\u064a\u0645\u0627\u0646",B.a2N,null)
B.atP=new A.iN("Shahadah","\u0627\u0644\u0634\u0647\u0627\u062f\u0629","Testifying that none has the right to be worshipped except Allah, and that Muhammad is the Messenger of Allah.")
B.atR=new A.iN("Salah","\u0627\u0644\u0635\u0644\u0627\u0629","The five daily prayers: Fajr, Dhuhr, Asr, Maghrib, and Isha.")
B.atM=new A.iN("Zakat","\u0627\u0644\u0632\u0643\u0627\u0629","The obligatory charity on wealth that reaches the nisab, after a lunar year. On cash it is 2.5%.")
B.atK=new A.iN("Sawm","\u0627\u0644\u0635\u0648\u0645","Fasting the month of Ramadan, from the start of Fajr until Maghrib.")
B.atI=new A.iN("Hajj","\u0627\u0644\u062d\u062c","The pilgrimage to Makkah once in a lifetime, for whoever is able to make the journey.")
B.a4d=A.a(s([B.atP,B.atR,B.atM,B.atK,B.atI]),t.ud)
B.atA=new A.QE("Five Pillars of Islam","\u0623\u0631\u0643\u0627\u0646 \u0627\u0644\u0625\u0633\u0644\u0627\u0645",B.a4d,null)
B.atB=new A.QF(null)
